using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using PhoneStore.Core.Contracts;
internal sealed partial class QaSuite
{
    async Task<long> Create(string route,object input){using var r=await admin.Send(route,input);Assert(r.IsSuccessStatusCode,"Create "+route+" status "+(int)r.StatusCode);return(await r.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetInt64();}
    async Task Administration(){
        await Check("UC06-001","Thêm/sửa/ngừng sản phẩm qua API","Kho0 khi tạo, sửa đúng, public404 khi ngừng",async()=>{var i=new ProductInput("API-PHONE","Sản phẩm API",brand,category,"Cấu hình","Mô tả",null,true,[new(0,"API-SKU","Đen",128,100m,true)]);var id=await Create("/api/admin/products",i);var p=await admin.Read<ProductDto>($"/api/admin/products/{id}");Assert(p.Variants.Single().OnHand==0);await Status(await admin.Send($"/api/admin/products/{id}",Input(p) with{Name="Tên sửa",Active=false},HttpMethod.Put),200);await Status(await anon.Get($"/api/catalog/{id}"),404);});
        await Check("UC06-002","Mã/SKU trùng","400 và không tạo product rỗng",async()=>{var p=(await admin.Read<Page<ProductDto>>("/api/admin/products?Query=API-PHONE")).Items.Single();await using var db=Open();var before=await db.Products.CountAsync();await Status(await admin.Send("/api/admin/products",Input(p) with{Variants=[new(0,"FRESH-SKU","Đen",128,100m,true)]}),400);await Status(await admin.Send("/api/admin/products",Input(p) with{Code="DIFFERENT-CODE",Variants=[new(0,"API-SKU","Trắng",128,100m,true)]}),400);Assert(await db.Products.CountAsync()==before);});
        await Check("UC06-003","Bắt buộc/độ dài","Code31/tên201/SKU51 bị400",async()=>{var sample=new ProductInput("BOUNDARY","Tên",brand,category,"","",null,true,[new(0,"BOUND-SKU","Đen",128,100m,true)]);foreach(var invalid in new[]{sample with{Code=new string('A',31)},sample with{Name=new string('A',201)},sample with{Variants=[new(0,new string('S',51),"Đen",128,1,true)]},sample with{Name=""}})await Status(await admin.Send("/api/admin/products",invalid),400);});
        await Check("UC06-004","Tổ hợp biến thể trùng","400, rollback cả product",async()=>{await Status(await admin.Send("/api/admin/products",new ProductInput("DUP-COMB","Tên",brand,category,"","",null,true,[new(0,"COMB1","Đen",128,100m,true),new(0,"COMB2","Đen",128,200m,true)])),400);});
        await Check("UC06-005","Biên giá âm/zero/lẻ3 số/quá lớn","Từng trường hợp400",async()=>{foreach(var price in new[]{-1m,0m,1.001m,1000000000000m})await Status(await admin.Send("/api/admin/products",new ProductInput("PRICE-BOUND","Tên",brand,category,"","",null,true,[new(0,"PRICE-BOUND","Đen",128,price,true)])),400);});
        await Check("UC06-008","Overpost tồn trong thông tin sản phẩm","Không thay đổi tồn DB",async()=>{var v=await Fixture(3);var p=await ProductFor(v[0].Id);var body=JsonSerializer.SerializeToNode(Input(p))!;body["onHand"]=9999;await Status(await admin.Send($"/api/admin/products/{p.Id}",body,HttpMethod.Put),200);Assert((await Stock(v[0].Id)).OnHand==3);});
        await Check("QA-IMAGE-URL","URL ảnh không an toàn","javascript/http không được lưu",async()=>{var v=await Fixture();var p=await ProductFor(v[0].Id);foreach(var image in new[]{"javascript:alert(1)","http://example.test/phone.png"})await Status(await admin.Send($"/api/admin/products/{p.Id}",Input(p) with{ImageUrl=image},HttpMethod.Put),400);});
        await Check("UC07-001","Tìm khách hàng","Tìm SĐT A chỉ trả A",async()=>{var list=await admin.Read<Page<CustomerDto>>("/api/admin/customers?query=0911111111");Assert(list.Total==1&&list.Items[0].Id==aId);});
        await Check("UC07-002","Admin cập nhật khách hàng","Chỉ hồ sơ mục tiêu được cập nhật",async()=>{var before=await b.Read<UserDto>("/api/profile");await Status(await admin.Send($"/api/admin/customers/{bId}",new CustomerInput("B được sửa",before.Phone,before.Email,before.Address,true),HttpMethod.Put),200);Assert((await b.Read<UserDto>("/api/profile")).FullName=="B được sửa");});
        await Check("UC07-007","Response không chứa hash/mật khẩu","Không có tên thuộc tính nhạy cảm",async()=>{using var r=await admin.Get("/api/admin/customers");var text=await r.Content.ReadAsStringAsync();Assert(!text.Contains("password",StringComparison.OrdinalIgnoreCase)&&!text.Contains("hash",StringComparison.OrdinalIgnoreCase));});
        await Check("UC08-001","CRUD mềm NCC","Create/update/deactivate lưu và vẫn tra cứu được",async()=>{var id=await Create("/api/admin/suppliers",new SupplierInput("QA-NCC","NCC QA","0933333333","Địa chỉ",true));await Status(await admin.Send($"/api/admin/suppliers/{id}",new SupplierInput("QA-NCC","NCC sửa",null,null,false),HttpMethod.Put),200);var list=await admin.Read<List<SupplierDto>>("/api/admin/suppliers?query=QA-NCC");Assert(list.Single().Name=="NCC sửa"&&!list[0].Active);});
        var variant=(await Fixture(0))[0];long receipt=0;
        await Check("UC08-002","Lập phiếu nháp và sửa dòng","Tổng theo3x200, dòng chỉ1",async()=>{receipt=await Create("/api/admin/purchases",new PurchaseInput(supplier,[new(variant.Id,2,100m)]));var p=await admin.Read<PurchaseDto>($"/api/admin/purchases/{receipt}");await Status(await admin.Send($"/api/admin/purchases/{receipt}",new PurchaseInput(supplier,[new(variant.Id,3,200m)],p.Version),HttpMethod.Put),200);p=await admin.Read<PurchaseDto>($"/api/admin/purchases/{receipt}");Assert(p.Total==600&&p.Lines.Single().Quantity==3);});
        await Check("UC08-003","Số lượng/giá nhập sai","400 với0/âm/giá0",async()=>{foreach(var line in new[]{new PurchaseLineInput(variant.Id,0,100),new(variant.Id,-1,100),new(variant.Id,1,0)})await Status(await admin.Send("/api/admin/purchases",new PurchaseInput(supplier,[line])),400);});
        await Check("UC08-004","Nháp không cộng tồn","Tồn0 trước chốt",async()=>Assert((await Stock(variant.Id)).OnHand==0));
        await Check("UC08-005","Xác nhận phiếu","Thực3, Total600, confirmerAdmin",async()=>{var p=await admin.Read<PurchaseDto>($"/api/admin/purchases/{receipt}");await Status(await admin.Send($"/api/admin/purchases/{receipt}/confirm",new TransitionRequest(p.Version,Guid.NewGuid())),200);p=await admin.Read<PurchaseDto>($"/api/admin/purchases/{receipt}");Assert(p.Status=="DA_XAC_NHAN"&&p.Total==600&&p.Confirmer!=null&&(await Stock(variant.Id)).OnHand==3);});
        await Check("UC08-007","Phiếu chốt không sửa/hủy","409 và kho vẫn3",async()=>{var p=await admin.Read<PurchaseDto>($"/api/admin/purchases/{receipt}");await Status(await admin.Send($"/api/admin/purchases/{receipt}",new PurchaseInput(supplier,[new(variant.Id,50,1)],p.Version),HttpMethod.Put),409);await Status(await admin.Send($"/api/admin/purchases/{receipt}/cancel",new TransitionRequest(p.Version,Guid.NewGuid())),409);Assert((await Stock(variant.Id)).OnHand==3);});
        await Check("UC08-012","Nhập giá vốn không tự sửa giá bán","Giá bán vẫn1 triệu",async()=>Assert((await ProductFor(variant.Id)).Variants.Single().Price==1000000m));
        await Check("QA-ADJUST","Kiểm kê lý do/giữ/version","Chặn dưới giữ, chặn thiếu lý do, sửa đúng có log",async()=>{var order=await Place(a,await Cart(a,[variant]));var s=await Stock(variant.Id);await Status(await admin.Send($"/api/admin/stock/{variant.Id}/adjust",new AdjustmentInput(0,"QA",s.Version,Guid.NewGuid())),400);await Status(await admin.Send($"/api/admin/stock/{variant.Id}/adjust",new AdjustmentInput(4,"",s.Version,Guid.NewGuid())),400);await Status(await admin.Send($"/api/admin/stock/{variant.Id}/adjust",new AdjustmentInput(4,"Kiểm kê QA",s.Version,Guid.NewGuid())),200);var current=await Stock(variant.Id);Assert(current.OnHand==4&&current.Reserved==1);await Status(await admin.Send($"/api/admin/stock/{variant.Id}/adjust",new AdjustmentInput(5,"QA",s.Version,Guid.NewGuid())),409);await Move(order.Id,"cancel");});
        await Check("UC08-013","Nhật ký actor/chứng từ/lý do","Có NHAP và DIEU_CHINH, diễn giải đầy đủ",async()=>{var log=await admin.Read<Page<MovementDto>>($"/api/admin/movements?variantId={variant.Id}");Assert(log.Items.Any(x=>x.Kind=="NHAP"&&x.Document!=null)&&log.Items.Any(x=>x.Kind=="DIEU_CHINH"&&x.Reason=="Kiểm kê QA")&&log.Items.All(x=>!string.IsNullOrEmpty(x.Actor)));});
    }
}
